def transform(grid):
    n = len(grid[0])
    k = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if abs(c - k) == r and r <= k:
                out[r][c] = 2
            elif r >= 3 and abs(c - k) < r and (c - r - k) % 4 == 0:
                out[r][c] = 1
    return out
